import { authClient } from "@/lib/auth-client";

export function SessionStatus() {
  const { data, isPending, error } = authClient.useSession();

  if (isPending) return <p>Loading session…</p>;
  if (error) return <p>Could not load the session.</p>;
  return <p>{data ? `Welcome, ${data.user.name}` : "Signed out"}</p>;
}

import { betterAuth } from "better-auth";
import { createAuthMiddleware } from "better-auth/api";
import { APIError } from "better-auth/api";

export const auth = betterAuth({
  hooks: {
    before: createAuthMiddleware(async (ctx) => {
      if (ctx.path !== "/sign-up/email") return;
      if (!ctx.body?.email?.endsWith("@example.com")) {
        throw new APIError("BAD_REQUEST", {
          message: "Email must use the example.com domain",
        });
      }
      return {
        context: {
          ...ctx,
          body: { ...ctx.body, name: "Invited user" },
        },
      };
    }),
  },
});
